import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.B-bxTAy7.js";const C=JSON.parse('{"title":"DMA 与缓存一致性","description":"DMA 搬运的三种数据流、CPU 不参与的边界、D-Cache 与外设内存不同步的问题。","frontmatter":{"title":"DMA 与缓存一致性","description":"DMA 搬运的三种数据流、CPU 不参与的边界、D-Cache 与外设内存不同步的问题。"},"headers":[],"relativePath":"prereq/dma-cache.md","filePath":"prereq/dma-cache.md","lastUpdated":null}'),n={name:"prereq/dma-cache.md"};function l(s,a,i,c,d,g){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="dma-与缓存一致性" tabindex="-1">DMA 与缓存一致性 <a class="header-anchor" href="#dma-与缓存一致性" aria-label="Permalink to &quot;DMA 与缓存一致性&quot;">​</a></h1><h2 id="结论先行" tabindex="-1">结论先行 <a class="header-anchor" href="#结论先行" aria-label="Permalink to &quot;结论先行&quot;">​</a></h2><ul><li><strong>DMA</strong> 是独立于 CPU 的搬运工：外设数据就绪后，DMA 自动把它搬进内存（或反向），<strong>全程不占 CPU</strong>。</li><li>典型收益：100 kHz 采样若每次转换完成都进中断，CPU 每秒被打断 10 万次；改用 DMA 循环模式，CPU 只在「一批收满」时才被打扰一次。</li><li>三种常见模式：<strong>Normal</strong>（搬完停）、<strong>Circular</strong>（循环，连续采样必备）、<strong>双缓冲</strong>（一半满触发一次，实现流水线）。</li><li><strong>缓存一致性</strong>是带 D-Cache 的芯片（如 STM32F7/H7、M7）上的核心坑：DMA 直接写内存，<strong>CPU 的 Cache 里还是旧值</strong>；反过来 CPU 写完的数据可能还滞留在 Cache 里，DMA 读不到。</li><li>解决办法是<strong>显式维护 Cache</strong>：DMA 写内存后 CPU 读之前要 <strong>Invalidate</strong>（失效）对应区域；CPU 写内存之后 DMA 读之前要 <strong>Clean</strong>（回写）。</li></ul><p><strong>为什么它承重</strong>：Cache 带来的性能与「读到的值是旧的」这两件事同时存在，只有一半人知道。F7/H7 上不处理 Cache，DMA 采回来的数据会是一段旧值，调试时几乎无法定位。</p><h2 id="典型数值" tabindex="-1">典型数值 <a class="header-anchor" href="#典型数值" aria-label="Permalink to &quot;典型数值&quot;">​</a></h2><ul><li>100 kHz 采样、每点 12 位：中断方式每秒 10 万次进入；DMA 循环缓冲 1000 点，则每秒只进 100 次中断（降低 1000 倍）。</li><li>STM32F7 的 D-Cache 行大小是 <strong>32 字节</strong>。做 Cache 操作时地址必须<strong>按 32 字节对齐</strong>、长度取 32 的整数倍，否则失效范围不完整。</li><li>CPU 读 DMA 缓冲前调用 <code>SCB_InvalidateDCache_by_Addr(addr, size)</code>；CPU 写完缓冲、DMA 要读时调用 <code>SCB_CleanDCache_by_Addr(addr, size)</code>。</li><li>M7 的 AXI 总线带宽远高于 DMA 请求速率——所以 DMA 的瓶颈通常不是总线，而是<strong>数据量与内存布局</strong>。</li></ul><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>在带 Cache 的芯片上用 DMA 但没做 Cache 维护</strong>：读到的数据是「上一批的」。</li><li>Cache 操作<strong>地址没按 32 字节对齐</strong>——失效只覆盖了半行，另外半行还是脏数据。</li><li>忘了 DMA 缓冲区<strong>不能放在栈上</strong>（函数返回后失效），要放在全局或静态区。</li><li>环形缓冲区写指针与读指针<strong>不是原子操作</strong>：多字节变量被中断读到一半的值，需要临界区保护。</li><li>在 F1/F4（无 Cache）上写这套代码是多余的，但无害；反过来在 F7 上漏掉就是故障——<strong>移植时最容易被漏掉的一步</strong>。</li></ul><div class="tip custom-block" id="ex-dma-cache-1"><p class="custom-block-title">例 1 · DMA 采回来的是旧数据，怎么办</p><p>现象：STM32H7 上用 DMA 循环采 ADC，示波器看到输入在变，但屏幕上数字几乎不动，偶尔跳一下。</p><p><strong>原因</strong>：H7 的 D-Cache 是写回（write-back）的。DMA 把新数据直接写进 SRAM，<strong>不经过 Cache</strong>；CPU 读的时候命中的是 Cache 里的旧行——只要那个行还没被替换，CPU 就一直读到旧值。</p><p><strong>处理</strong>（三步，缺一不可）：</p><ol><li>DMA 缓冲区放在<strong>全局数组</strong>里，且起始地址按 32 字节对齐（用 <code>__attribute__((aligned(32)))</code>）；</li><li>DMA 一批搬完（回调里），先 <strong>Clean</strong> 不必要、<strong>Invalidate</strong> 该区域： <code>SCB_InvalidateDCache_by_Addr((uint32_t*)buf, sizeof(buf));</code></li><li>之后 CPU 才去读 <code>buf</code>。</li></ol><blockquote><p><strong>为什么这么想</strong> Cache 是一份「本地副本」，DMA 是「外来写入者」——它不知道 Cache 存在，也不通知 Cache。于是本地副本与真实内存分家。Invalidate 就是命令 CPU「别信你的副本了，下次去内存取」。</p></blockquote></div><blockquote><p>深入：完整内容见 <a href="./../embedded/adc-dma">10 · ADC 与 DMA</a></p></blockquote>',10)])])}const D=e(n,[["render",l]]);export{C as __pageData,D as default};
